#!/usr/bin/env python3
"""FS3 v192 - hangar and support with an info card, fixed rearm text.

    Hangar (V)  The list keeps hull, shield, speed and agility; on the
                right a fixed info card for the hull under the pointer:
                the 3D model (turns on hover, wheel zooms), guns and volley,
                banks, bars against the best hull with a white mark for
                yours, your fit and racks. Long names are set smaller
                instead of being cut (GTF Herc Mk II).
    Support (S) The same card: hull, anti-fighter and heavy beams, turrets
                and launchers read from the mount data, what the ship does
                for you (wings and hangar, rearm, the Colossus' 60 s) and
                the tickets. 16 more models (cruisers, corvettes,
                destroyers, Colossus) come in the zips.
    Names       Vasudan support ships are GTVA in the FS2 era: GVC, GVCv,
                GVD (PV only in the FS1 era, as on the field).
    Rearm       The info text keeps two fixed lines, the facts two fixed
                rows, so nothing below moves (Silvio).
    Testing     &ship=<hull> starts in that hull, e.g. &ship=bosekhmet.

Needs v191. Edits src/, hlp_mounts_final.json and the simulations. Run
assemble.py afterwards.
"""
import base64
import os
import sys

if not os.path.exists("src/58_model3d.js"):
    sys.exit("Abbruch: erst v191 einspielen.")
if "drawInfoCard" in open("src/70_ui.js", encoding="utf-8").read():
    sys.exit("Abbruch: v192 ist schon eingespielt.")

F = {}
def load(p):
    if p not in F: F[p] = open(p, encoding="utf-8").read()
def rep(p, old, new, count=1):
    load(p)
    n = F[p].count(old)
    if n != count:
        sys.exit("Abbruch (%s): Suchtext %d-mal gefunden, erwartet %d.\n%s" % (p, n, count, old[:200]))
    F[p] = F[p].replace(old, new)
